const L = require('lv-automation').w05;
const j = $input.first().json;
const h = j.headers || {};
const p = L.parseHttp(h, j.body || {}, $env, Date.now());
return [{ json: { lane: 'http', ...p, hdr: { 'x-test-token': h['x-test-token'] || '', 'x-test-now': h['x-test-now'] || '' } } }];

const L = require('lv-automation').w05;
const p = $('Parse + verify caller (w05.parseHttp)').first().json;
const cnt = $('Guard counters (bk_ip / bk_lead)').first().json;
const ran = $('Turnstile siteverify (book)').isExecuted;
const tin = ran ? ($('Turnstile siteverify (book)').first() || {}).json : null;
const g = L.bookGuard(p.guard, { ip_hits: cnt.ip_hits, lead_hits: cnt.lead_hits, turnstile: tin && tin.success !== undefined ? tin : null }, $env);
return [{ json: g.ok ? { ...p, bot_check: g.bot_check } : { lane: 'http', ok: false, status: g.status, body: g.body, reason: g.reason } }];

const L = require('lv-automation').w05;
const dns = require('dns').promises;
const x = $('Load lead, broker, replay, live booking').first().json;
const c = $input.first().json.req ? $input.first().json : ($('Parse + verify caller (w05.parseHttp)').isExecuted ? $('Parse + verify caller (w05.parseHttp)').first().json : $('Normalise sub-call (w05.parseSub)').first().json);
const wall = Date.now();
const now = L.clockFor(c.hdr || {}, $env, !!(x.lead && x.lead.is_synthetic), wall);
const mx = {};
const d = L.emailDomain(c.req.email || (x.lead && x.lead.email) || '');
if (d) { try { const r = await Promise.race([dns.resolveMx(d), new Promise((_, rj) => setTimeout(() => rj(new Error('t')), 300))]); mx[d] = Array.isArray(r) && r.length > 0; } catch (e) { mx[d] = false; } }
const ctx = { lane: c.lane, mode: c.mode, req: c.req, lead: x.lead, broker: x.broker, broker_by_user: x.broker_by_user, existing: x.existing, live: x.live, mx, now, test_clock: now !== wall };
const dec = L.decide(ctx);
return [{ json: { ctx, dec, action: dec.action, lane: c.lane, status: dec.status, body: dec.body, wa: dec.wa || null, to: 'lead', lead_id: x.lead ? x.lead.id : null, w10: dec.w10 || null } }];

const L = require('lv-automation').w05;
const d = $('Decide (w05.decide + MX)').first().json;
const r = L.afterCheck(d.ctx, d.dec, $input.first().json);
return [{ json: { ...d, check: r, action: r.action, status: r.status, body: r.body, wa: r.wa || null, row: r.row || null } }];

const L = require('lv-automation').w05;
const d = $('After re-check (w05.afterCheck)').first().json;
const ex = $input.first().json.existing;
if (ex) return [{ json: { ...d, action: 'replay', status: 201, body: L.publicBody(ex), wa: null } }];
const t = L.taken(d.ctx, d.dec.plan, []);
return [{ json: { ...d, action: 'taken', status: 409, body: t.body, wa: t.wa || null } }];

const L = require('lv-automation').w05;
const d = $('Decide (w05.decide + MX)').first().json;
return [{ json: { access_token: $input.first().json.access_token || '', event: L.graphEvent(d.ctx, d.dec.plan, { portalUrl: $env.PORTAL_URL }) } }];

const L = require('lv-automation').w05;
const d = $('Decide (w05.decide + MX)').first().json;
return [{ json: L.sharedEventItem(d.ctx, d.dec.plan, { HOWZIT_MAILBOX: $env.HOWZIT_MAILBOX, SMC_SHARED_CALENDAR_ID: $env.SMC_SHARED_CALENDAR_ID }, { portalUrl: $env.PORTAL_URL }) }];

const L = require('lv-automation').w05;
const d = $('Decide (w05.decide + MX)').first().json;
const row = $('Insert appointment (re-check overlap + buffer, idempotent)').first().json;
const ev = L.afterEvent($input.first().json);
const f = L.finish(d.ctx, d.dec.plan, row, ev, { site: $env.SITE_URL, ics_secret: $env.LEAD_TOKEN_SECRET });
return [{ json: { ...d, booking: row, ev, f, lane: d.lane, status: f.response.status, body: f.response.body } }];

