INSERT INTO public.lead_activities (lead_id, brand_id, broker_id, cycle_id, workflow, actor_type, activity_type, payload, occurred_at, idempotency_key)
VALUES ($1::uuid, NULLIF($2, '')::uuid, $3::uuid, NULLIF($4, '')::uuid, 'W05', 'lead', 'booking_created', jsonb_build_object('booking_id', $5::text, 'start', $6::text, 'method', $7::text, 'booked_via', $8::text, 'graph_event', $9::boolean), now(), 'w05:booked:' || $5)
ON CONFLICT (idempotency_key) DO NOTHING RETURNING id;

parameters.jsCode:
const L = require('lv-automation').w05;
const j = $input.first().json;
const src = j.f ? j : ($('After event (w05.finish)').isExecuted ? $('After event (w05.finish)').first().json : j);
return [{ json: { lane: src.lane, status: src.status || 200, body: src.body || {}, wa: src.wa || null, to: 'lead', lead_id: src.lead_id || (src.ctx && src.ctx.lead && src.ctx.lead.id) || null, f: src.f || null } }];

const L = require('lv-automation').w05;
const j = $input.first().json;
const out = [];
if (j.wa) out.push({ kind: 'wa', to: 'lead', lead_id: j.lead_id, wa: j.wa });
const f = j.f; if (!f) return out.map((x) => ({ json: x }));
if (f.invite) out.push({ kind: 'mail', mail: { message: f.invite.message, saveToSentItems: true } });
if (f.broker.email) out.push({ kind: 'mail', mail: { message: { subject: f.broker.email.subject, body: { contentType: 'Text', content: f.broker.email.body }, toRecipients: [{ emailAddress: { address: f.broker.email.to } }] }, saveToSentItems: true } });
if (f.broker.wa) out.push({ kind: 'wa', to: 'broker', lead_id: j.lead_id, wa: f.broker.wa });
if (f.lead_wa) out.push({ kind: 'wa', to: 'lead', lead_id: j.lead_id, wa: f.lead_wa });
for (const k of ['w06', 'w09', 'w07', 'capi', 'ask_email', 'alert']) if (f[k]) out.push({ kind: k, ...f[k] });
return out.map((x) => ({ json: x }));

const L = require('lv-automation').w05;
const j = $input.first().json;
const r = L.parseIcsRequest({ headers: j.headers || {}, params: j.params || {}, query: j.query || {} }, $env, Date.now());
return [{ json: r }];

parameters.query:
-- I-45j: only the columns the invite already carries; nothing from the leads table is selected.
SELECT (SELECT to_jsonb(k) FROM (SELECT a.id, a.client_id, a.appointment_date, a.ends_at, a.method, a.status, a.join_url, a.booked_at FROM public.appointments a WHERE a.id::text = $1 AND a.brand_id IS NOT NULL) k) AS booking,
       (SELECT COALESCE(b.adviser_name, b.contact_person) FROM public.brokers b JOIN public.appointments a ON a.broker_id = b.id WHERE a.id::text = $1) AS adviser;

