const L = require('lv-automation').w05;
const c = $('Verify .ics caller (w05.parseIcsRequest)').first().json;
const x = $input.first().json;
return [{ json: L.icsResponse(x.booking, { adviser: x.adviser || '', caller: c }) }];

const L = require('lv-automation').w05;
const x = $input.first().json;
const req = $('Normalise sub-call (w05.parseSub)').first().json.req;
const p = L.planUpdateMethod({ req, booking: x.booking, lead: x.lead, broker: x.broker, now: Date.now() });
const invite = p.action === 'patch' ? L.inviteMail({ lead: x.lead, broker: x.broker }, p.plan, x.booking, {}) : null;
return [{ json: { ...p, booking: x.booking, ask: p.ask_email || null, mail: invite ? { message: invite.message, saveToSentItems: true } : null, kind: p.action } }];

const L = require('lv-automation').w05;
const x = $('Plan method change (w05.planUpdateMethod)').first().json;
const t = L.graphEventTarget(x.booking, x.broker, { HOWZIT_MAILBOX: $env.HOWZIT_MAILBOX, SMC_SHARED_CALENDAR_ID: $env.SMC_SHARED_CALENDAR_ID });
return [{ json: { target: t, route: t.error || t.route === 'none' ? 'skip' : t.route, broker_id: x.booking.broker_id } }];

const L = require('lv-automation').w05;
const p = $('Plan method change (w05.planUpdateMethod)').first().json;
return p.mail ? [{ json: { kind: 'mail', mail: p.mail } }] : [];
